import {T,mesh,box,scene,camera,renderer} from './visuals3.js';
export const foodNames=['Pão','Frango','Alface','Tomate','Molho'];
export const foodFiles=['bread','chicken','lettuce','tomato','sauce'];
export function foodModel(name,parent,x=0,y=0,z=0,scale=1){let r=new T.Group();r.position.set(x,y,z);r.scale.setScalar(scale);parent.add(r);
if(name==='Pão'){mesh(new T.CylinderGeometry(.54,.56,.06,32),'#e6c98e',0,.04,0,r);for(let i=0;i<16;i++){let a=i*2.4,d=.12+(i%5)*.08;mesh(new T.SphereGeometry(.025,5,4),'#a97e49',Math.cos(a)*d,.079,Math.sin(a)*d,r).scale.y=.2}}
if(name==='Frango'){for(let i=0;i<3;i++){let m=mesh(new T.IcosahedronGeometry(.32,2),'#c69864',(i-1)*.32,.13,0,r);m.scale.set(.65,.55,1.4);for(let j=-1;j<=1;j++){let mark=box((i-1)*.32,.285,j*.18,.16,.012,.025,'#81512f',r);mark.rotation.y=-.3}}}
if(name==='Alface'){for(let i=0;i<7;i++){let a=i*2.4,m=mesh(new T.SphereGeometry(.31,10,6),'#77a558',Math.cos(a)*.18,.08+i*.025,Math.sin(a)*.18,r);m.scale.set(1,.12,.65);m.rotation.y=a;box(Math.cos(a)*.12,.12+i*.025,Math.sin(a)*.12,.02,.02,.38,'#b2ca7b',r).rotation.y=a}}
if(name==='Tomate'){mesh(new T.SphereGeometry(.38,20,14),'#d75c49',0,.3,0,r).scale.y=.85;for(let i=0;i<5;i++){let leaf=mesh(new T.ConeGeometry(.07,.25,3),'#5d834b',Math.sin(i*1.26)*.1,.64,Math.cos(i*1.26)*.1,r);leaf.rotation.z=.8;leaf.rotation.y=i*1.26}box(0,.7,0,.035,.18,.035,'#557743',r)}
if(name==='Molho'){mesh(new T.CylinderGeometry(.16,.19,.6,20),'#eee3bc',0,.32,0,r);mesh(new T.CylinderGeometry(.15,.16,.12,16),'#ae614c',0,.67,0,r);mesh(new T.ConeGeometry(.07,.24,12),'#bf7958',0,.84,0,r);box(0,.35,.17,.2,.24,.015,'#9eaa79',r)}
return r}
function removeGroup(g){g.traverse(o=>o.geometry?.dispose());g.removeFromParent()}
export class Kitchen{
constructor({root,onDone,onHint,onSound,isBlocked}){this.root=root;this.onDone=onDone;this.onHint=onHint;this.onSound=onSound;this.isBlocked=isBlocked;this.active=false;this.rolled=false;this.plate=new T.Group();root.add(this.plate);this.plate.position.set(0,1.75,.15);mesh(new T.CylinderGeometry(.64,.68,.05,32),'#e9e4d6',2.7,1.71,.1,root);this.board=box(0,1.7,.1,2.5,.09,1.55,'#bd9567',root);for(let i=0;i<6;i++)box(-1+i*.4,1.751,.1,.012,.005,1.4,'#aa8057',root);
this.work=new T.Group();this.work.position.set(0,1.8,.1);root.add(this.work);this.work.visible=false;this.knife=new T.Group();this.knife.position.set(1,.15,0);this.work.add(this.knife);box(0,0,.2,.12,.09,.55,'#564c49',this.knife);let blade=box(0,.01,-.27,.055,.24,.52,'#d9e1df',this.knife);blade.rotation.z=-.08;for(let i=0;i<2;i++)mesh(new T.SphereGeometry(.025,6,4),'#d5c5a0',.065,0,.1+i*.17,this.knife);
this.panel=document.createElement('section');this.panel.id='cookingPanel';this.panel.hidden=true;document.body.append(this.panel);this.ray=new T.Raycaster();this.plane=new T.Plane(new T.Vector3(0,1,0),-2.29);this.canvas=renderer.domElement;
this.events={pointerdown:e=>this.down(e),pointermove:e=>this.move(e),pointerup:e=>this.up(e),pointercancel:e=>this.cancelDrag(e)};for(let [k,fn]of Object.entries(this.events))this.canvas.addEventListener(k,fn,{capture:true});}
open(name){if(this.active)return;this.active=true;this.name=name;this.cuts=0;this.progress=0;this.pour=0;this.ready=false;this.selected=name!=='Frango'&&name!=='Tomate'&&name!=='Alface';this.task=['Frango','Tomate','Alface'].includes(name)?'cut':name==='Molho'?'pour':name==='Enrolar'?'roll':'stretch';this.work.visible=true;this.plate.visible=false;for(let o of this.root.userData.awning||[])o.visible=false;this.resetFood();this.panel.hidden=false;this.drawPanel();this.makeGuide()}
resetFood(){if(this.food)removeGroup(this.food);this.food=new T.Group();this.work.add(this.food);this.pieces=[];if(this.task==='cut'){for(let i=0;i<3;i++){let r=new T.Group();this.food.add(r);r.position.x=(i-1)*.32;this.pieces.push(r);if(this.name==='Frango'){let p=mesh(new T.IcosahedronGeometry(.33,2),'#c69864',0,.13,0,r);p.scale.set(.6,.65,1.45);for(let j=-1;j<=1;j++)box(0,.32,j*.2,.16,.012,.025,'#81512f',r)}else if(this.name==='Tomate'){let m=mesh(new T.CylinderGeometry(.39,.39,.29,24),'#df624d',0,.4,0,r);m.rotation.z=Math.PI/2;for(let j=0;j<6;j++){let a=j/6*Math.PI*2;mesh(new T.SphereGeometry(.035,6,4),'#f1cb89',.151,.4+Math.sin(a)*.22,Math.cos(a)*.22,r)}}else{let m=mesh(new T.SphereGeometry(.38,12,8),'#78a75a',0,.13,0,r);m.scale.set(.45,.3,1.15);box(0,.22,0,.03,.025,.75,'#c4d69b',r)}}}else if(this.task==='pour'){foodModel('Pão',this.food);foodModel('Frango',this.food,0,.1,0,.65);this.bottle=foodModel('Molho',this.food,.7,.4,-.1,.65)}else if(this.task==='roll'){foodModel('Pão',this.food);foodModel('Frango',this.food,0,.1,0,.7);foodModel('Alface',this.food,0,.18,0,.65)}else foodModel('Pão',this.food,0,0,0,.7)}
drawPanel(){this.panel.innerHTML='<div class="cookTop"><small>PREPARO DE PERTO</small><button id="leaveCook">Voltar à bancada</button></div><h3>'+({cut:'Cortar '+this.name.toLowerCase(),pour:'Finalizar com molho',roll:'Enrolar o shawarma',stretch:'Abrir o pão'})[this.task]+'</h3><p id="cookHint">'+({cut:'Pegue a faca à direita. Arraste do ponto dourado até o final da linha.',pour:'Segure o frasco para distribuir o molho.',roll:'Arraste pela guia para dobrar e enrolar.',stretch:'Passe o dedo pela guia para abrir a massa.'})[this.task]+'</p><div class="cookMeter"><i id="cookFill"></i></div><button id="cookTool" class="'+(this.selected?'selected':'')+'"><img src="icons/'+(this.task==='cut'?'knife':this.task==='pour'?'sauce':'bread')+'.svg" alt="">'+(this.task==='cut'?'Pegar faca':this.task==='pour'?'Segurar molho':'Seguir a guia')+'</button><button id="addCook" hidden class="primary">'+(this.task==='roll'?'Concluir shawarma':'Adicionar ao preparo')+'</button>';
this.panel.querySelector('#leaveCook').onclick=()=>this.close();let tool=this.panel.querySelector('#cookTool');tool.onpointerdown=e=>{e.preventDefault();this.selected=true;tool.classList.add('selected');if(this.task==='cut')this.panel.querySelector('#cookHint').textContent='Faca na mão. Faça dois cortes seguindo as guias.';if(this.task==='pour')this.pouring=true};for(let ev of ['pointerup','pointercancel','pointerleave'])tool.addEventListener(ev,()=>this.pouring=false);this.panel.querySelector('#addCook').onclick=()=>this.commit();}
makeGuide(){if(this.guide)removeGroup(this.guide);this.guide=new T.Group();this.work.add(this.guide);if(this.task==='pour')return;let height=this.task==='stretch'?.065:this.name==='Tomate'?.82:this.name==='Alface'?.28:.35;this.plane.constant=-(this.work.position.y+height);let x=this.task==='cut'?-.16+this.cuts*.32:0;this.start=new T.Vector3(this.task==='stretch'?-.65:x,.07,this.task==='stretch'?0:.56);this.end=new T.Vector3(this.task==='stretch'?.65:x,.07,this.task==='stretch'?0:-.56);for(let i=0;i<12;i++){let p=this.start.clone().lerp(this.end,i/11);let d=mesh(new T.SphereGeometry(.025,6,4),'#ffe1a2',p.x,height,p.z,this.guide,.7);d.material=d.material.clone();d.material.depthTest=false}this.marker=mesh(new T.SphereGeometry(.065,10,8),'#ffe8ac',this.start.x,height,this.start.z,this.guide,.8);this.marker.material.depthTest=false}
ground(e){this.ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);let p=new T.Vector3();if(!this.ray.ray.intersectPlane(this.plane,p))return null;return p.sub(this.work.position)}
down(e){if(!this.active||this.isBlocked())return;e.stopImmediatePropagation();if(!this.selected){this.onHint('Pegue a faca à direita antes de cortar.');return}if(this.ready||this.task==='pour')return;let p=this.ground(e);if(!p)return;let a=this.start.clone().setY(0);p.y=0;if(p.distanceTo(a)>.4){this.onHint('Comece pelo ponto dourado da guia.');return}this.dragId=e.pointerId;this.travel=0;this.invalid=false;this.canvas.setPointerCapture(e.pointerId);this.move(e)}
move(e){if(!this.active||this.isBlocked())return;e.stopImmediatePropagation();if(e.pointerId!==this.dragId)return;let p=this.ground(e);if(!p)return;this.follow(p)}
follow(p){let a=this.start.clone().setY(0),b=this.end.clone().setY(0),delta=b.clone().sub(a),point=p.clone().setY(0),t=point.clone().sub(a).dot(delta)/delta.lengthSq(),nearest=a.clone().addScaledVector(delta,Math.max(0,Math.min(1,t)));if(point.distanceTo(nearest)>.3){this.invalid=true;return}this.travel=Math.max(this.travel||0,t);this.progress=Math.min(1,this.travel);if(this.task==='roll'){this.food.scale.x=1-this.progress*.3;this.food.rotation.z=this.progress*.18}this.knife.position.set(point.x,.16,point.z);this.knife.rotation.z=-.25;this.panel.querySelector('#cookFill').style.width=(this.task==='cut'?(this.cuts+this.progress)/2:this.progress)*100+'%'}
up(e){if(!this.active)return;e.stopImmediatePropagation();if(e.pointerId!==this.dragId)return;this.dragId=null;if(!this.invalid&&this.travel>.85)this.completeStroke();else this.onHint('Siga a linha inteira, do ponto dourado ao fim.');this.knife.rotation.z=0;this.knife.position.set(1,.15,0)}
cancelDrag(){this.dragId=null;this.pouring=false;this.progress=0}
completeStroke(){this.onSound(620,.1,'triangle');if(this.task==='cut'){this.cuts++;this.pieces.forEach((p,i)=>p.userData.targetX=(i-1)*.32+(i<this.cuts?-.16:.16));if(this.cuts<2){this.progress=0;this.makeGuide();this.panel.querySelector('#cookHint').textContent='Primeiro corte feito. Siga a próxima linha.';return}}this.finish()}
finish(){if(this.ready)return;this.ready=true;this.progress=1;if(this.guide)this.guide.visible=false;this.panel.querySelector('#cookFill').style.width='100%';this.panel.querySelector('#cookHint').textContent=this.task==='roll'?'Pronto para servir.':'Preparo concluído. Adicione ao shawarma.';this.panel.querySelector('#cookTool').hidden=true;this.panel.querySelector('#addCook').hidden=false;if(this.task==='roll'){removeGroup(this.food);this.food=new T.Group();this.work.add(this.food);let wrap=mesh(new T.CylinderGeometry(.23,.24,1.1,20),'#e7c78e',0,.25,0,this.food);wrap.rotation.z=Math.PI/2;foodModel('Alface',this.food,.52,.28,0,.4)}}
commit(){if(!this.ready)return;let name=this.name;this.close();this.onDone(name)}
close(){this.active=false;this.cancelDrag();this.work.visible=false;this.plate.visible=true;this.panel.hidden=true;for(let o of this.root.userData.awning||[])o.visible=true}
update(dt){if(!this.active||this.isBlocked())return;if(this.pouring&&!this.ready){this.pour+=dt;this.progress=Math.min(1,this.pour/1.1);this.bottle.rotation.z=-.65;this.panel.querySelector('#cookFill').style.width=this.progress*100+'%';if(this.pour>=1.1){for(let j=0;j<6;j++)box(-.3+j*.12,.32,Math.sin(j*2)*.2,.07,.025,.4,'#eee0b7',this.food);this.finish()}}for(let p of this.pieces)if(p.userData.targetX!==undefined)p.position.x=T.MathUtils.damp(p.position.x,p.userData.targetX,8,dt);if(this.task==='stretch'&&!this.ready)this.food.scale.x=1+this.progress*.45}
updatePlate(names,rolled){for(let c of [...this.plate.children])removeGroup(c);names.forEach((n,i)=>{let m=foodModel(n,this.plate,0,i*.07,0,.65);if(n==='Molho')m.visible=false});if(rolled){for(let c of [...this.plate.children])c.visible=false;let w=mesh(new T.CylinderGeometry(.2,.23,1,20),'#e7c78e',0,.2,0,this.plate);w.rotation.z=Math.PI/2;foodModel('Alface',this.plate,.45,.2,0,.35)}}
dispose(){for(let [k,fn]of Object.entries(this.events))this.canvas.removeEventListener(k,fn,{capture:true});this.panel.remove()}
}
